import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void flash_attn_kernel(const half* __restrict__ Q,
                                   const half* __restrict__ K,
                                   const half* __restrict__ V,
                                   half* __restrict__ O,
                                   int batch, int heads, int seq, int dim,
                                   float scale) {
    int idx = blockIdx.x; // over batch*heads*seq
    int row = idx % seq;
    int bh = idx / seq;
    int b = bh / heads;
    int h = bh % heads;

    const half* Qp = Q + ((size_t)b * heads + h) * (size_t)seq * dim + (size_t)row * dim;
    const half* Kp = K + ((size_t)b * heads + h) * (size_t)seq * dim;
    const half* Vp = V + ((size_t)b * heads + h) * (size_t)seq * dim;
    half* Op = O + ((size_t)b * heads + h) * (size_t)seq * dim + (size_t)row * dim;

    extern __shared__ float smem[];
    float* q_sh = smem;          // dim floats
    float* score_sh = smem + dim; // seq floats

    __shared__ float sdata[1024];

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // Load Q row into shared memory (vectorized half2 loads)
    // Load Q row into shared memory (vectorized float4 = 8 half loads)
    {
        const float4* Qp4 = reinterpret_cast<const float4*>(Qp);
        int dim4 = dim / 8;
        for (int i = tid; i < dim4; i += nthreads) {
            float4 qf4 = Qp4[i];
            half2 q0 = *reinterpret_cast<half2*>(&qf4.x);
            half2 q1 = *reinterpret_cast<half2*>(&qf4.y);
            half2 q2 = *reinterpret_cast<half2*>(&qf4.z);
            half2 q3 = *reinterpret_cast<half2*>(&qf4.w);
            float2 f0 = __half22float2(q0);
            float2 f1 = __half22float2(q1);
            float2 f2 = __half22float2(q2);
            float2 f3 = __half22float2(q3);
            int base = i * 8;
            q_sh[base + 0] = f0.x; q_sh[base + 1] = f0.y;
            q_sh[base + 2] = f1.x; q_sh[base + 3] = f1.y;
            q_sh[base + 4] = f2.x; q_sh[base + 5] = f2.y;
            q_sh[base + 6] = f3.x; q_sh[base + 7] = f3.y;
        }
    }
    __syncthreads();
    // Compute raw scores: assume nthreads == seq (vectorized half2 dot product)
    // Compute raw scores: assume nthreads == seq (vectorized float4 dot product, 8 halfs per load)
    if (tid < seq) {
        const half* Krow = Kp + (size_t)tid * dim;
        const float4* Krow4 = reinterpret_cast<const float4*>(Krow);
        float sum = 0.f;
        int dim4 = dim / 8;
        for (int i = 0; i < dim4; ++i) {
            float4 kf4 = Krow4[i];
            half2 k0 = *reinterpret_cast<half2*>(&kf4.x);
            half2 k1 = *reinterpret_cast<half2*>(&kf4.y);
            half2 k2 = *reinterpret_cast<half2*>(&kf4.z);
            half2 k3 = *reinterpret_cast<half2*>(&kf4.w);
            float2 kf0 = __half22float2(k0);
            float2 kf1 = __half22float2(k1);
            float2 kf2 = __half22float2(k2);
            float2 kf3 = __half22float2(k3);
            int base = i * 8;
            sum += q_sh[base + 0] * kf0.x + q_sh[base + 1] * kf0.y;
            sum += q_sh[base + 2] * kf1.x + q_sh[base + 3] * kf1.y;
            sum += q_sh[base + 4] * kf2.x + q_sh[base + 5] * kf2.y;
            sum += q_sh[base + 6] * kf3.x + q_sh[base + 7] * kf3.y;
        }
        score_sh[tid] = sum * scale;
    }
    __syncthreads();
    // Reduce max
    float maxval = -1e30f;
    for (int i = tid; i < seq; i += nthreads) {
        maxval = fmaxf(maxval, score_sh[i]);
    }
    sdata[tid] = maxval;
    __syncthreads();
    for (int s = nthreads / 2; s > 0; s >>= 1) {
        if (tid < s) sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        __syncthreads();
    }
    float row_max = sdata[0];
    __syncthreads();

    // Compute exp and sum
    float sum_exp = 0.f;
    for (int i = tid; i < seq; i += nthreads) {
        float e = expf(score_sh[i] - row_max);
        score_sh[i] = e;
        sum_exp += e;
    }
    sdata[tid] = sum_exp;
    __syncthreads();
    for (int s = nthreads / 2; s > 0; s >>= 1) {
        if (tid < s) sdata[tid] += sdata[tid + s];
        __syncthreads();
    }
    float total = sdata[0];
    __syncthreads();

    // Normalize
    for (int i = tid; i < seq; i += nthreads) {
        score_sh[i] /= total;
    }
    __syncthreads();

    // Compute output: O = attn @ V (vectorized half2 loads/stores)
    int dim2_out = dim / 2;
    for (int k2 = tid; k2 < dim2_out; k2 += nthreads) {
        int k = k2 * 2;
        float acc0 = 0.f, acc1 = 0.f;
        for (int j = 0; j < seq; ++j) {
            float s = score_sh[j];
            const half2* Vrow2 = reinterpret_cast<const half2*>(Vp + (size_t)j * dim + k);
            float2 vf = __half22float2(*Vrow2);
            acc0 += s * vf.x;
            acc1 += s * vf.y;
        }
        half2* Op2 = reinterpret_cast<half2*>(Op + k);
        *Op2 = __floats2half2_rn(acc0, acc1);
    }
}

torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda(), "Q must be a CUDA tensor");
    TORCH_CHECK(Q.dtype() == torch::kFloat16, "Q must be float16");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Inputs must be contiguous");

    int batch = Q.size(0);
    int heads = Q.size(1);
    int seq = Q.size(2);
    int dim = Q.size(3);

    auto O = torch::empty_like(Q);

    float scale = 1.0f / sqrtf((float)dim);

    int total_blocks = batch * heads * seq;
    int threads = seq; // assume power of two, matches seq_len

    size_t shared_mem_size = (size_t)(dim + seq) * sizeof(float);

    flash_attn_kernel<<<total_blocks, threads, shared_mem_size>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        batch, heads, seq, dim, scale
    );

    return O;
}
"""

cpp_source = r"""
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

flash_attn_ext = load_inline(
    name="flash_attn_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["flash_attention_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        Q = Q.contiguous()
        K = K.contiguous()
        V = V.contiguous()
        return flash_attn_ext.flash_attention_forward(Q, K, V)


batch_size = 2
num_heads = 32
sequence_length = 256
embedding_dimension = 1024


def get_inputs():
    Q = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    K = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    V = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    return [Q, K, V]


def get_init_inputs():
    return []

